INSERT INTO "public"."content_who_are_they" ("prompt_id", "axis", "content", "anchor", "detail") VALUES
	('c7923041-f896-49e8-94b6-2264074e1e3e', 'NeedForReassurance', 'If someone replies slower than usual, I assume something is wrong.', true, NULL),
	('d7479bd0-e79f-4f94-aca1-2d578d5874f0', 'NeedForReassurance', 'I need frequent reassurance that a relationship is okay.', true, NULL),
	('7cf4e583-68b7-4b7c-ac4a-67b4633b46f5', 'NeedForReassurance', 'Uncertainty in dating makes me anxious.', true, NULL),
	('86f4e38f-1927-4de3-96c7-a11e13a1f6f4', 'NeedForReassurance', 'I worry about being replaced by someone better.', false, NULL),
	('bbbe2614-b6eb-4a74-af2b-20c8a306c5a6', 'NeedForReassurance', 'I read into small changes in tone or energy.', false, NULL),
	('ca23830c-32dd-40d3-a527-7fa7efb2e8ac', 'NeedForReassurance', 'I feel unsettled when I don’t know where I stand with someone.', false, NULL),
	('44b57cc5-b1d1-436a-9cd2-e4d4120f0b84', 'NeedForReassurance', 'After conflict, I need reassurance sooner rather than later.', false, NULL),
	('c69003ae-8f5e-4d05-bf4c-78610a59dd5f', 'NeedForReassurance', 'I get anxious when a partner needs a lot of space.', false, NULL),
	('9b8eed16-7c28-4646-a08b-b7160a172ea5', 'NeedForReassurance', 'I can become preoccupied with how a relationship is going.', false, NULL),
	('ef086726-d179-4991-b0f7-a74c6c3fe464', 'NeedForReassurance', 'I find it hard to relax unless I feel consistently chosen.', false, NULL),
	('34cf2f0b-5459-4fa5-a588-30e2145c89a6', 'ConflictApproach', 'When conflict comes up, my instinct is to avoid it rather than engage.', true, NULL),
	('997c7ae7-6b06-4fc0-8bb3-c733d63d3c33', 'ConflictApproach', 'I’d rather let things cool off than talk about an issue immediately.', true, NULL),
	('ff62d578-4a67-4ca5-bd52-8b70f06c872a', 'ConflictApproach', 'Unresolved tension makes me uncomfortable enough that I want to address it quickly.', true, NULL),
	('b7d75aa8-fd2e-4580-8700-80d1a3a5759b', 'ConflictApproach', 'I’m comfortable having difficult conversations, even if they’re emotionally charged.', false, NULL),
	('ea5e4299-fdb0-47a7-b378-de74cd11b238', 'ConflictApproach', 'If an argument feels intense, I tend to shut down or disengage.', false, NULL),
	('d37e7066-a2a0-4118-a499-321a235d27c0', 'ConflictApproach', 'I’d rather talk things through than let issues sit beneath the surface.', false, NULL),
	('0d7d1c0c-f78a-445e-8fab-f7a52a1ee85c', 'ConflictApproach', 'I avoid conflict because I worry it will make things worse.', false, NULL),
	('7771fe60-f96c-41db-b72e-2d27e877ff0b', 'ConflictApproach', 'I believe problems should be addressed as soon as they arise.', false, NULL),
	('129f7b71-f8e3-4fe1-bbe9-51f687164893', 'ConflictApproach', 'I feel overwhelmed when disagreements escalate.', false, NULL),
	('1932afb0-6c87-4ae6-b995-fe294179ca7f', 'ConflictApproach', 'I’m okay with a bit of tension if it means clearing the air.', false, NULL),
	('6db1a892-e86d-48dc-8249-ee39b9582c62', 'RepairStrategy', 'I need to process my emotions on my own before reconnecting.', true, NULL),
	('bb586611-46f3-4f5b-ada4-c2d506e83c05', 'RepairStrategy', 'Being comforted by my partner helps me calm down after conflict.', true, NULL),
	('6002da27-7599-4fec-acb3-ecf219780240', 'RepairStrategy', 'I feel better once I’ve had time and space to regulate myself.', true, NULL),
	('a4317891-1b18-49e4-a140-ccdd3c7273c0', 'RepairStrategy', 'I need emotional closeness to feel okay again after an argument.', true, NULL),
	('22f86fc6-f9fd-41cf-b84a-d61e1b722eaf', 'RepairStrategy', 'I don’t like being pushed to talk before I’ve settled internally.', false, NULL),
	('b7d26215-d85c-43de-a87f-5e9ca421b6a4', 'RepairStrategy', 'Physical or emotional reassurance helps me recover faster.', false, NULL),
	('ed057243-3784-426c-a372-429f9ae6f2bf', 'RepairStrategy', 'I prefer fixing things privately rather than leaning on someone else.', false, NULL),
	('b4084842-1ca1-4a11-bc12-8ed4b2d6b7ba', 'RepairStrategy', 'I feel disconnected if we don’t reconnect emotionally after conflict.', false, NULL),
	('e28b0991-1ce4-49b8-a84c-8851ea7f129c', 'RepairStrategy', 'Once I’ve calmed myself down, I’m ready to reconnect.', false, NULL),
	('cf190779-6301-4257-99e2-8f0e60f5e2d5', 'RepairStrategy', 'I rely on shared reassurance rather than internal coping to move past arguments.', false, NULL),
	('f040a103-7b51-40f0-8d2c-d2eefc1d0b1d', 'FutureFocus', 'When I date someone, I’m usually thinking about whether this could be long-term.', true, NULL),
	('214ef8fc-ac3f-4d0f-bb94-3b5a2445c85b', 'FutureFocus', 'I prefer to see where things go rather than think too far ahead.', true, NULL),
	('68ed90b5-c52c-43c4-b7e4-598bf5fccf70', 'FutureFocus', 'I’m intentional about dating because I want something that lasts.', true, NULL),
	('aaef73e0-ffc4-450b-a672-1f55207bfb1c', 'FutureFocus', 'I focus more on how a relationship feels now than where it’s heading.', true, NULL),
	('6527bcc2-8ac9-4862-85cd-3b8ad9fab963', 'FutureFocus', 'I think about how someone would fit into my future life.', false, NULL),
	('b51d6672-7e46-4d6d-9e37-f921d8b2c0ea', 'FutureFocus', 'Planning far ahead in relationships feels unnecessary to me.', false, NULL),
	('861df667-3b1a-42a2-a335-fc8618f14544', 'FutureFocus', 'I’m dating with a clear sense of what I eventually want.', false, NULL),
	('4fe06d9c-f933-4b76-9f2a-7ad5494c6294', 'FutureFocus', 'I don’t like putting expectations on where a relationship should go.', false, NULL),
	('dcf87f6b-5d1d-4ae1-8502-7f6f9fdec6dc', 'FutureFocus', 'I think relationships should develop naturally without a long-term plan.', false, NULL),
	('72ba9b5a-0c82-4ed7-a7b1-9e1f862b0abc', 'FutureFocus', 'I’m comfortable dating without knowing what the end goal is.', false, NULL),
	('a29772f0-9eae-496a-95b5-3a2faeba3b49', 'RelationshipPace', 'I like to take my time before getting emotionally invested.', true, NULL),
	('098334d2-b9da-43b4-b3fa-5df5a5b35c18', 'RelationshipPace', 'When I feel a connection, I tend to move quickly.', true, NULL),
	('abff5377-192c-4cf3-81f8-38e5d8eccf47', 'RelationshipPace', 'I prefer relationships to develop slowly and deliberately.', true, NULL),
	('998b269a-cab8-4f0d-9a33-f6814f55a857', 'RelationshipPace', 'I’m comfortable getting close fast if it feels right.', true, NULL),
	('35e0c5a1-dc74-4cdc-aef9-7185c18e6f85', 'RelationshipPace', 'I like to build trust over time rather than rush things.', false, NULL),
	('4214160f-0e9a-4dbb-a6b2-5018a52d495a', 'RelationshipPace', 'I don’t like holding back my feelings once I know I’m interested.', false, NULL),
	('aee941f2-0765-49fd-a188-824909e6d279', 'RelationshipPace', 'I’m cautious about escalating a relationship too quickly.', false, NULL),
	('5929e5b1-2601-4328-8d1c-07f4f9bc9175', 'RelationshipPace', 'I tend to follow my feelings rather than set a pace intentionally.', false, NULL),
	('fc6cd720-7350-4718-bad4-d88b87ba6b4d', 'RelationshipPace', 'I’m comfortable with early intensity in relationships.', false, NULL),
	('1be9b387-377e-4ce1-82f8-bb84db68c55d', 'RelationshipPace', 'I prefer to let emotional closeness grow gradually.', false, NULL),
	('692d0e06-02b9-432b-8b61-43ac33f8ae93', 'MoralFraming', 'Doing what’s fair matters more to me than taking someone’s side.', true, NULL),
	('e27e1de6-7df3-4f06-b30f-310344114de2', 'MoralFraming', 'I believe loyalty to people I care about comes before abstract principles.', true, NULL),
	('0eb4dbc1-19fa-4c32-82bb-56f499595755', 'MoralFraming', 'I’d rather be honest and fair than blindly supportive.', true, NULL),
	('9c0246de-867a-4aa7-b2ea-37ce82a5852d', 'MoralFraming', 'Standing by my partner matters more to me than being objectively right.', true, NULL),
	('d788e55e-0ae7-4936-94da-cd1c6b0251bf', 'MoralFraming', 'If someone is wrong, I think it’s important to say so, even if it’s uncomfortable.', false, NULL),
	('7896b876-1b01-4ec9-ae59-ae9cc131e9a0', 'MoralFraming', 'I believe relationships work best when people back each other, even in messy situations.', false, NULL),
